<script setup lang="ts">
import type { FieldLevel } from '../../types'
defineProps<{levels:FieldLevel[]}>();defineEmits<{update:[key:string,patch:Partial<FieldLevel>]}>()
</script>
<template><div class="table-scroll"><table class="field-table"><thead><tr><th>模板字段</th><th>分组</th><th>矢量要求</th><th>可推导</th><th>项目默认值</th><th>人工补充</th><th>允许空</th><th>平台必填</th><th>缺失处理</th></tr></thead><tbody><tr v-for="f in levels" :key="f.key"><td><strong>{{f.field}}</strong><small class="mono">{{f.key}}</small><small v-if="f.requiredWhen">适用：{{f.requiredWhen.field==='is_confirmed'?'人工确认是确权地块':f.requiredWhen.field+' = '+f.requiredWhen.equals}}</small></td><td>{{{basic:'基本',confirm:'确权',ext:'扩展'}[f.group]}}</td><td>{{{required:'必需',recommended:'建议',optional:'非必需'}[f.vectorRequirement]}}</td><td>{{f.derivable?'是':'—'}}</td><td><input v-if="f.defaultable" :aria-label="`${f.field}默认值`" :value="f.defaultValue??''" placeholder="未设置" @change="$emit('update',f.key,{defaultValue:($event.target as HTMLInputElement).value||null})"><span v-else class="muted">不自动填充</span></td><td>{{f.manualFill?'可人工补':'—'}}</td><td><input type="checkbox" :aria-label="`${f.field}允许空`" :checked="f.allowEmpty" @change="$emit('update',f.key,{allowEmpty:($event.target as HTMLInputElement).checked})"></td><td><select :aria-label="`${f.field}平台必填`" :value="f.platformRequired" @change="$emit('update',f.key,{platformRequired:($event.target as HTMLSelectElement).value as FieldLevel['platformRequired']})"><option value="unknown">待确认</option><option value="yes">已确认必填</option><option value="no">非必填</option></select></td><td><span class="badge" :class="['plot_code','geom_wkt'].includes(f.key)||f.platformRequired==='yes'?'block':f.platformRequired==='unknown'?'info':!f.allowEmpty?'warn':'neutral'">{{['plot_code','geom_wkt'].includes(f.key)?'结构阻断':f.platformRequired==='yes'?'适用时阻断':f.platformRequired==='unknown'?'仅提示':!f.allowEmpty?'项目警告':'允许空'}}</span></td></tr><tr v-if="!levels.length"><td colspan="9" class="empty">没有符合条件的字段</td></tr></tbody></table></div></template>
